<?php
namespace App\Services;
use App\Models\{BookingServis,JenisServis,KendaraanPelanggan,Pelanggan};
use Illuminate\Support\Facades\DB;
use RuntimeException;
class BookingServisService {
 private function code():string{$code='BSV-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(4)));while(BookingServis::where('kode_booking',$code)->exists())$code='BSV-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(4)));return $code;}
 public function create(int $customerId,int $vehicleId,int $serviceTypeId,string $date,string $time,?string $complaint,?string $note,?int $preferredPetugasId=null):BookingServis{return DB::transaction(function()use($customerId,$vehicleId,$serviceTypeId,$date,$time,$complaint,$note,$preferredPetugasId){$customer=Pelanggan::findOrFail($customerId);$vehicle=$customer->kendaraan()->where('status','aktif')->findOrFail($vehicleId);$type=JenisServis::where('status','aktif')->findOrFail($serviceTypeId);if(strtotime($date.' '.$time)<=now()->timestamp)throw new RuntimeException('Tanggal dan jam harus di masa depan.');app(ServiceSchedulingService::class)->assertAvailable($date,$time,$type->id_jenis_servis);if($preferredPetugasId)app(ServicePersonnelAvailabilityService::class)->eligible($preferredPetugasId,$date,$time,$type->id_jenis_servis);$b=new BookingServis();$b->forceFill(['kode_booking'=>$this->code(),'id_pelanggan'=>$customer->id_pelanggan,'id_kendaraan_pelanggan'=>$vehicle->id_kendaraan_pelanggan,'id_jenis_servis'=>$type->id_jenis_servis,'id_preferred_petugas'=>$preferredPetugasId,'tanggal'=>$date,'jam'=>$time,'keluhan'=>$complaint,'catatan'=>$note,'status'=>'menunggu']);$b->save();try{app(ServiceNotificationService::class)->forAdminBooking($b);}catch(\Throwable $notificationFailure){report($notificationFailure);}return $b;});}
 public function confirm(int $id):void{$this->transition($id,'diterima');}
 public function reject(int $id):void{$this->transition($id,'ditolak');}
 public function cancel(int $id,int $customerId):void{DB::transaction(function()use($id,$customerId){$b=BookingServis::whereKey($id)->where('id_pelanggan',$customerId)->lockForUpdate()->first();if(!$b||!in_array($b->status,['menunggu','diterima'],true))throw new RuntimeException('Booking servis tidak dapat dibatalkan.');$b->forceFill(['status'=>'dibatalkan'])->save();});}
 private function transition(int $id,string $target):void{DB::transaction(function()use($id,$target){$b=BookingServis::lockForUpdate()->with('pelanggan')->findOrFail($id);$allowed=['menunggu'=>['diterima','ditolak'],'diterima'=>[],'ditolak'=>[],'dibatalkan'=>[],'diproses'=>[],'selesai'=>[]];if(!in_array($target,$allowed[$b->status]??[],true))throw new RuntimeException('Perubahan status booking servis tidak diizinkan.');$b->forceFill(['status'=>$target])->save();$title=$target==='diterima'?'Booking servis diterima':'Booking servis ditolak';$message=$target==='diterima'?'Booking '.$b->kode_booking.' sudah diterima. Silakan menunggu jadwal pemeriksaan kendaraan.':'Booking '.$b->kode_booking.' belum dapat diterima oleh bengkel. Silakan hubungi YZA Automotive untuk informasi lebih lanjut.';if($b->pelanggan?->id_user)app(ServiceNotificationService::class)->forBooking((int)$b->pelanggan->id_user,$b->id_booking_servis,$title,$message);});}
}
